import {
    Box, Checkbox, Link, TableCell, TableRow, Typography,
} from '@mui/material';
import { useMemo, type ReactNode } from 'react';
import { TableVirtuoso, type TableComponents, type TableVirtuosoProps } from 'react-virtuoso';
import { JSON_ARRAY_DEFAULT_COLUMN_WIDTH, type JsonDataDocument } from '../../services/json/json_data_document';
import { isJsonObject, isJsonPrimitive, type JsonLocationSegment, type JsonValue } from '../../services/json/json_types';
import { JsonScalarEditor } from './json_scalar_editor';
import { JsonArrayActionsFooter } from './json_array_actions_footer';
import { JsonArrayColumnHeaderCell } from './json_array_column_header_cell';
import { JsonArrayVirtualTable } from './json_array_virtual_table';
import { JsonArrayVirtualTableHead } from './json_array_virtual_table_head';

const JSON_ARRAY_ESTIMATED_ROW_HEIGHT = 53;
const JSON_ARRAY_OVERSCAN = 106;
const JSON_ARRAY_SELECTION_COLUMN_WIDTH = 48;

interface JsonArrayEditorProps {
    document: JsonDataDocument;
    value: JsonValue[];
}

interface JsonArrayColumn {
    name: string;
    width: number;
}

interface JsonArrayTableContext {
    columns: JsonArrayColumn[];
    document: JsonDataDocument;
    location: readonly JsonLocationSegment[];
    objectTable: boolean;
    rowCount: number;
    selectedRows: ReadonlySet<number>;
    tableWidth: number;
}

const JSON_ARRAY_TABLE_COMPONENTS: TableComponents<JsonValue, JsonArrayTableContext> = {
    Table: JsonArrayVirtualTable,
    TableHead: JsonArrayVirtualTableHead,
};

function objectColumns(rows: JsonValue[]) {
    const columns: string[] = [];
    const seen = new Set<string>();
    rows.forEach((row) => {
        if (!isJsonObject(row)) return;
        Object.keys(row).forEach((key) => {
            if (seen.has(key)) return;
            seen.add(key);
            columns.push(key);
        });
    });

    return columns;
}

function renderHeader(columns: JsonArrayColumn[], document: JsonDataDocument) {
    return (
        <TableRow>
            <TableCell padding="checkbox" style={{ width: JSON_ARRAY_SELECTION_COLUMN_WIDTH }} sx={{ bgcolor: 'background.paper', boxSizing: 'border-box' }}>
                <Typography variant="caption">Select</Typography>
            </TableCell>
            {columns.map(({ name, width }) => (
                <JsonArrayColumnHeaderCell column={name} document={document} key={name} width={width} />
            ))}
        </TableRow>
    );
}

function renderRow(rowIndex: number, row: JsonValue, context: JsonArrayTableContext): ReactNode {
    const { columns, document, location, objectTable, selectedRows } = context;
    const selected = selectedRows.has(rowIndex);
    const selectionCellSx = { boxSizing: 'border-box', ...(selected ? { bgcolor: 'action.selected' } : undefined) };
    const cellSx = { ...selectionCellSx, '& .MuiTextField-root': { minWidth: 0, width: '100%' } };
    const handleSelection = () => {
        const nextSelection = new Set(selectedRows);
        if (selected) nextSelection.delete(rowIndex);
        else nextSelection.add(rowIndex);
        document.setSelectedRows([...nextSelection]);
    };

    return (
        <>
            <TableCell padding="checkbox" style={{ width: JSON_ARRAY_SELECTION_COLUMN_WIDTH }} sx={selectionCellSx}>
                <Checkbox
                    checked={selected}
                    onChange={handleSelection}
                    slotProps={{ input: { 'aria-label': `Select row ${rowIndex + 1}` } }}
                />
            </TableCell>
            {columns.map(({ name: column, width }) => {
                const fieldPresent = !objectTable || isJsonObject(row) && Object.hasOwn(row, column);
                const fieldValue = objectTable && isJsonObject(row) ? row[column] : row;
                const accessibleName = objectTable ? `${column} row ${rowIndex + 1}` : `Value row ${rowIndex + 1}`;
                const fieldLocation = objectTable ? [...location, rowIndex, column] : [...location, rowIndex];
                const handleOpen = () => {
                    document.drillInto(rowIndex);
                    if (objectTable) document.drillInto(column);
                };
                const handleMissingChange = (nextValue: JsonValue) => {
                    const nextRow = { ...(row as { [key: string]: JsonValue }), [column]: nextValue };
                    document.setValue([...location, rowIndex], nextRow, 'json-editor');
                };

                return (
                    <TableCell key={`${rowIndex}:${column}`} style={{ width }} sx={cellSx}>
                        {!fieldPresent ? (
                            <JsonScalarEditor
                                accessibleName={accessibleName}
                                document={document}
                                location={fieldLocation}
                                onChange={handleMissingChange}
                                value=""
                            />
                        ) : isJsonPrimitive(fieldValue) ? (
                            <JsonScalarEditor
                                accessibleName={accessibleName}
                                document={document}
                                location={fieldLocation}
                                value={fieldValue}
                            />
                        ) : (
                            <Link aria-label={`Open ${accessibleName}`} component="button" onClick={handleOpen} type="button" variant="body2">
                                Open
                            </Link>
                        )}
                    </TableCell>
                );
            })}
        </>
    );
}

/** Array table with service-owned multi-row selection and ordered row operations. */
export function JsonArrayEditor({ document, value }: JsonArrayEditorProps) {
    const snapshot = document.getSnapshot();
    const selectedRows = useMemo(() => new Set(snapshot.selectedRows), [snapshot.selectedRows]);
    const objectTable = useMemo(() => value.length > 0 && value.every(isJsonObject), [value]);
    const columnNames = useMemo(() => objectTable ? objectColumns(value) : ['values'], [objectTable, value]);
    const columns = useMemo<JsonArrayColumn[]>(
        () => columnNames.map((name) => ({ name, width: snapshot.arrayColumnWidths.get(name) ?? JSON_ARRAY_DEFAULT_COLUMN_WIDTH })),
        [columnNames, snapshot.arrayColumnWidths],
    );
    const tableWidth = columns.reduce((total, { width }) => total + width, JSON_ARRAY_SELECTION_COLUMN_WIDTH);
    const tableContext = useMemo<JsonArrayTableContext>(() => ({
        columns,
        document,
        location: snapshot.location,
        objectTable,
        rowCount: value.length,
        selectedRows,
        tableWidth,
    }), [columns, document, objectTable, selectedRows, snapshot.location, tableWidth, value.length]);
    const fixedHeaderContent = useMemo<TableVirtuosoProps<JsonValue, JsonArrayTableContext>['fixedHeaderContent']>(
        () => () => renderHeader(columns, document),
        [columns, document],
    );

    return (
        <Box sx={{ display: 'flex', flex: 1, flexDirection: 'column', minHeight: 0 }}>
            <TableVirtuoso
                components={JSON_ARRAY_TABLE_COMPONENTS}
                context={tableContext}
                data={value}
                defaultItemHeight={JSON_ARRAY_ESTIMATED_ROW_HEIGHT}
                fixedHeaderContent={fixedHeaderContent}
                itemContent={renderRow}
                overscan={JSON_ARRAY_OVERSCAN}
                style={{ flex: 1, height: '100%', minHeight: 0, width: '100%' }}
            />
            <JsonArrayActionsFooter document={document} />
        </Box>
    );
}

import { Table } from '@mui/material';
import type { CSSProperties, ReactNode } from 'react';

interface JsonArrayVirtualTableProps {
    children?: ReactNode;
    context: { rowCount: number; tableWidth: number };
    style?: CSSProperties;
}

/** MUI table surface used by the virtualized JSON array. */
export function JsonArrayVirtualTable(props: JsonArrayVirtualTableProps) {
    const { children, context, style } = props;

    return (
        <Table
            aria-label="JSON array"
            aria-rowcount={context.rowCount + 1}
            size="small"
            stickyHeader
            style={{ ...style, tableLayout: 'fixed', width: context.tableWidth }}
        >
            {children}
        </Table>
    );
}

import { TableHead } from '@mui/material';
import { forwardRef, type CSSProperties, type ReactNode } from 'react';

interface JsonArrayVirtualTableHeadProps {
    children?: ReactNode;
    context: unknown;
    style?: CSSProperties;
}

/** Supplies MUI's header context while retaining Virtuoso's sticky positioning. */
export const JsonArrayVirtualTableHead = forwardRef<HTMLTableSectionElement, JsonArrayVirtualTableHeadProps>(
    function JsonArrayVirtualTableHead(props, ref) {
        const { children, style } = props;

        return <TableHead ref={ref} style={style}>{children}</TableHead>;
    },
);

import { Box, TableCell } from '@mui/material';
import { useRef, useState, type KeyboardEvent, type PointerEvent } from 'react';
import { JSON_ARRAY_MIN_COLUMN_WIDTH, type JsonDataDocument } from '../../services/json/json_data_document';

const COLUMN_KEYBOARD_STEP = 24;
const SEPARATOR_HIT_TARGET_WIDTH = 12;

interface JsonArrayColumnHeaderCellProps {
    column: string;
    document: JsonDataDocument;
    width: number;
}

interface PointerResizeSession {
    pointerId: number;
    startClientX: number;
    startWidth: number;
}

/** Data column header with a keyboard- and pointer-resizable boundary. */
export function JsonArrayColumnHeaderCell({ column, document, width }: JsonArrayColumnHeaderCellProps) {
    const pointerResizeSessionRef = useRef<PointerResizeSession | null>(null);
    const [isResizing, setIsResizing] = useState(false);
    const handlePointerDown = (event: PointerEvent<HTMLDivElement>) => {
        event.preventDefault();
        pointerResizeSessionRef.current = { pointerId: event.pointerId, startClientX: event.clientX, startWidth: width };
        setIsResizing(true);
        event.currentTarget.setPointerCapture?.(event.pointerId);
    };
    const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
        const session = pointerResizeSessionRef.current;
        if (session?.pointerId !== event.pointerId) return;
        document.setArrayColumnWidth(column, session.startWidth + event.clientX - session.startClientX);
    };
    const finishPointerResize = (event: PointerEvent<HTMLDivElement>) => {
        if (pointerResizeSessionRef.current?.pointerId !== event.pointerId) return;
        pointerResizeSessionRef.current = null;
        setIsResizing(false);
        if (event.currentTarget.hasPointerCapture?.(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
    };
    const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
        const widthsByKey: Record<string, number> = {
            ArrowLeft: width - COLUMN_KEYBOARD_STEP,
            ArrowRight: width + COLUMN_KEYBOARD_STEP,
            Home: JSON_ARRAY_MIN_COLUMN_WIDTH,
        };
        const nextWidth = widthsByKey[event.key];
        if (nextWidth === undefined) return;
        event.preventDefault();
        document.setArrayColumnWidth(column, nextWidth);
    };

    return (
        <TableCell
            style={{ width }}
            sx={{ bgcolor: 'background.paper', boxSizing: 'border-box', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}
        >
            {column}
            <Box
                aria-label={`Resize ${column} column`}
                aria-orientation="vertical"
                aria-valuemin={JSON_ARRAY_MIN_COLUMN_WIDTH}
                aria-valuenow={Math.round(width)}
                onKeyDown={handleKeyDown}
                onLostPointerCapture={finishPointerResize}
                onPointerCancel={finishPointerResize}
                onPointerDown={handlePointerDown}
                onPointerMove={handlePointerMove}
                onPointerUp={finishPointerResize}
                role="separator"
                sx={{
                    bottom: 0,
                    cursor: 'col-resize',
                    outline: 'none',
                    position: 'absolute',
                    right: 0,
                    top: 0,
                    touchAction: 'none',
                    width: SEPARATOR_HIT_TARGET_WIDTH,
                    '&::before': {
                        bgcolor: isResizing ? 'primary.main' : 'divider',
                        bottom: 0,
                        content: '""',
                        left: '50%',
                        position: 'absolute',
                        top: 0,
                        transform: 'translateX(-50%)',
                        width: '1px',
                    },
                    '&:hover::before, &:focus-visible::before': { bgcolor: 'primary.main' },
                }}
                tabIndex={0}
            />
        </TableCell>
    );
}

import { Box, Typography } from '@mui/material';
import { useSyncExternalStore } from 'react';
import type { JsonDataDocument } from '../../services/json/json_data_document';
import { isJsonObject, isJsonPrimitive } from '../../services/json/json_types';
import { JsonArrayEditor } from './json_array_editor';
import { JsonBreadcrumbs } from './json_breadcrumbs';
import { JsonObjectEditor } from './json_object_editor';
import { JsonScalarEditor } from './json_scalar_editor';

interface JsonDataEditorProps {
    document: JsonDataDocument;
}

/** Standalone renderer for one service-owned JSON document. */
export function JsonDataEditor({ document }: JsonDataEditorProps) {
    const snapshot = useSyncExternalStore(document.subscribe, document.getSnapshot, document.getSnapshot);
    const value = document.getValue();
    const handleNavigate = (depth: number) => document.navigateTo(depth);

    return (
        <Box
            aria-label="JSON data editor"
            component="section"
            sx={{ display: 'flex', flex: 1, flexDirection: 'column', minHeight: 0, minWidth: 0 }}
        >
            {snapshot.unavailableReason ? (
                <Box sx={{ p: 2 }}>
                    <Typography color="error">{snapshot.unavailableReason}</Typography>
                </Box>
            ) : (
                <>
                    <JsonBreadcrumbs location={snapshot.location} onNavigate={handleNavigate} path={document.path} />
                    <Box sx={{ borderTop: 1, borderColor: 'divider', display: 'flex', flex: 1, flexDirection: 'column', minHeight: 0, overflow: 'auto' }}>
                        {Array.isArray(value) ? <JsonArrayEditor document={document} value={value} /> : null}
                        {isJsonObject(value) ? <JsonObjectEditor document={document} value={value} /> : null}
                        {isJsonPrimitive(value) ? (
                            <Box sx={{ p: 2 }}>
                                <JsonScalarEditor
                                    accessibleName="JSON value"
                                    document={document}
                                    location={snapshot.location}
                                    value={value}
                                />
                            </Box>
                        ) : null}
                    </Box>
                </>
            )}
        </Box>
    );
}

import { Checkbox, FormControlLabel, TextField } from '@mui/material';
import type { ChangeEvent, KeyboardEvent } from 'react';
import type { JsonDataDocument } from '../../services/json/json_data_document';
import type { JsonLocationSegment, JsonPrimitive } from '../../services/json/json_types';

interface JsonScalarEditorProps {
    accessibleName: string;
    document: JsonDataDocument;
    location: readonly JsonLocationSegment[];
    onChange?: (value: JsonPrimitive) => void;
    value: JsonPrimitive;
}

/** Type-preserving scalar control: edits never change value's JSON type. */
export function JsonScalarEditor(props: JsonScalarEditorProps) {
    const { accessibleName, document, location, onChange, value } = props;
    const updateValue = (nextValue: JsonPrimitive) => {
        if (onChange) {
            onChange(nextValue);
            return;
        }
        document.setValue(location, nextValue, 'json-editor');
    };

    if (typeof value === 'boolean') {
        const handleBooleanChange = (_event: ChangeEvent<HTMLInputElement>, checked: boolean) => {
            updateValue(checked);
        };

        return (
            <FormControlLabel
                disabled={document.readOnly}
                control={<Checkbox checked={value} onChange={handleBooleanChange} slotProps={{ input: { 'aria-label': accessibleName } }} />}
                label={String(value)}
            />
        );
    }

    if (typeof value === 'number') {
        const input = document.getNumberInput(location, value);
        const handleNumberChange = (event: ChangeEvent<HTMLInputElement>) => {
            document.setNumberInput(location, event.target.value);
        };
        const handleNumberBlur = () => {
            document.commitNumberInput(location, 'json-editor');
        };
        const handleNumberKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
            if (event.key === 'Enter') {
                document.commitNumberInput(location, 'json-editor');
                return;
            }
            if (event.key === 'Escape') document.resetNumberInput(location);
        };

        return (
            <TextField
                disabled={document.readOnly}
                error={input.invalid}
                helperText={input.invalid ? 'Enter a valid JSON number' : undefined}
                onBlur={handleNumberBlur}
                onChange={handleNumberChange}
                onKeyDown={handleNumberKeyDown}
                size="small"
                slotProps={{ htmlInput: { 'aria-label': accessibleName, inputMode: 'decimal' } }}
                value={input.text}
            />
        );
    }

    if (value === null) {
        return (
            <TextField
                size="small"
                slotProps={{ htmlInput: { 'aria-label': accessibleName, readOnly: true } }}
                value="null"
            />
        );
    }

    const handleStringChange = (event: ChangeEvent<HTMLInputElement>) => {
        updateValue(event.target.value);
    };

    return (
        <TextField
            disabled={document.readOnly}
            onChange={handleStringChange}
            size="small"
            slotProps={{ htmlInput: { 'aria-label': accessibleName } }}
            value={value}
        />
    );
}

