                    '&:hover::before, &:focus-visible::before': { bgcolor: 'primary.main' },
                }}
                tabIndex={0}
            />
        </TableCell>
    );
}

import { Table } from '@mui/material';
import type { CSSProperties, ReactNode } from 'react';

interface JsonArrayVirtualTableProps {
    children?: ReactNode;
    context: { rowCount: number; tableWidth: number };
    style?: CSSProperties;
}

/** MUI table surface used by the virtualized JSON array. */
export function JsonArrayVirtualTable(props: JsonArrayVirtualTableProps) {
    const { children, context, style } = props;

    return (
        <Table
            aria-label="JSON array"
            aria-rowcount={context.rowCount + 1}
            size="small"
            stickyHeader
            style={{ ...style, tableLayout: 'fixed', width: context.tableWidth }}
        >
            {children}
        </Table>
    );
}

import AddOutlined from '@mui/icons-material/AddOutlined';
import ContentCopyOutlined from '@mui/icons-material/ContentCopyOutlined';
import ContentCutOutlined from '@mui/icons-material/ContentCutOutlined';
import ContentPasteOutlined from '@mui/icons-material/ContentPasteOutlined';
import DeleteOutlined from '@mui/icons-material/DeleteOutlined';
import { Box, IconButton, Tooltip } from '@mui/material';
import { useSyncExternalStore } from 'react';
import type { JsonDataDocument } from '../../services/json/json_data_document';
import { copyTextToClipboard, readTextFromClipboard } from '../../services/clipboard_text';
import { dialogService } from '../../services/dialog_service';

interface JsonArrayActionsFooterProps {
    document: JsonDataDocument;
}

function reportClipboardError(error: unknown, fallbackMessage: string) {
    dialogService.error(error, { fallbackMessage });
}

/** Footer bar with the row operations for the JSON array currently shown. */
export function JsonArrayActionsFooter({ document }: JsonArrayActionsFooterProps) {
    const { selectedRows } = useSyncExternalStore(document.subscribe, document.getSnapshot, document.getSnapshot);
    const mutationDisabled = document.readOnly;
    const selectionEmpty = selectedRows.length === 0;
    const handleAdd = () => document.addRow('json-editor');
    const handleDelete = () => document.deleteSelectedRows('json-editor');
    const handleCopy = async () => {
        try {
            await document.copySelectedRows(copyTextToClipboard);
        } catch (error) {
            reportClipboardError(error, 'JSON rows could not be copied');
        }
    };
    const handleCut = async () => {
        try {
            await document.cutSelectedRows(copyTextToClipboard, 'json-editor');
        } catch (error) {
            reportClipboardError(error, 'JSON rows could not be cut');
        }
    };
    const handlePaste = async () => {
        try {
            document.pasteRows(await readTextFromClipboard(), 'json-editor');
        } catch (error) {
            reportClipboardError(error, 'JSON rows could not be pasted');
        }
    };
    const actions = [
        { color: 'default', disabled: mutationDisabled, icon: <AddOutlined />, label: 'Add', onClick: handleAdd },
        { color: 'error', disabled: mutationDisabled || selectionEmpty, icon: <DeleteOutlined />, label: 'Delete', onClick: handleDelete },
        { color: 'default', disabled: selectionEmpty, icon: <ContentCopyOutlined />, label: 'Copy', onClick: handleCopy },
        { color: 'default', disabled: mutationDisabled || selectionEmpty, icon: <ContentCutOutlined />, label: 'Cut', onClick: handleCut },
        { color: 'default', disabled: mutationDisabled, icon: <ContentPasteOutlined />, label: 'Paste', onClick: handlePaste },
    ] as const;

    return (
        <Box
            aria-label="List actions"
            role="toolbar"
            sx={{ alignItems: 'center', backgroundColor: 'background.default', borderTop: 1, borderColor: 'divider', display: 'flex', flexShrink: 0, gap: 1, minWidth: 0, px: 2, py: 1.5 }}
        >
            {actions.map(({ color, disabled, icon, label, onClick }) => (
                <Tooltip key={label} title={label}>
                    <span>
                        <IconButton aria-label={label} color={color} disabled={disabled} onClick={onClick}>
                            {icon}
                        </IconButton>
                    </span>
                </Tooltip>
            ))}
        </Box>
    );
}

import { act, cleanup, render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { AppThemeProvider } from '../../theme/theme_provider';
import { JsonDataDocument } from '../../services/json/json_data_document';

const mocks = vi.hoisted(() => ({
    copyTextToClipboard: vi.fn(),
    dialogError: vi.fn(),
    readTextFromClipboard: vi.fn(),
}));

vi.mock('../../services/clipboard_text', () => ({
    copyTextToClipboard: mocks.copyTextToClipboard,
    readTextFromClipboard: mocks.readTextFromClipboard,
}));
vi.mock('../../services/dialog_service', () => ({ dialogService: { error: mocks.dialogError } }));

import { JsonArrayActionsFooter } from './json_array_actions_footer';

function renderFooter(document: JsonDataDocument) {
    return render(
        <AppThemeProvider>
            <JsonArrayActionsFooter document={document} />
        </AppThemeProvider>,
    );
}

describe('JsonArrayActionsFooter', () => {
    afterEach(() => {
        cleanup();
        vi.clearAllMocks();
    });

    it('shows the list actions as named icon-only buttons', () => {
        renderFooter(new JsonDataDocument('data.json', [1], false));
        const buttons = within(screen.getByRole('toolbar', { name: 'List actions' })).getAllByRole('button');

        expect(buttons.map((button) => button.getAttribute('aria-label'))).toEqual(['Add', 'Delete', 'Copy', 'Cut', 'Paste']);
        buttons.forEach((button) => {
            expect(button).toHaveTextContent(/^$/u);
            expect(button.querySelector('svg')).toBeInTheDocument();
        });
    });

    it('enables selection actions only after a row is selected', () => {
        const document = new JsonDataDocument('data.json', [1], false);
        renderFooter(document);

        expect(screen.getByRole('button', { name: 'Add' })).toBeEnabled();
        expect(screen.getByRole('button', { name: 'Paste' })).toBeEnabled();
        expect(screen.getByRole('button', { name: 'Delete' })).toBeDisabled();
        expect(screen.getByRole('button', { name: 'Copy' })).toBeDisabled();
        expect(screen.getByRole('button', { name: 'Cut' })).toBeDisabled();

        act(() => document.setSelectedRows([0]));

        expect(screen.getByRole('button', { name: 'Delete' })).toBeEnabled();
        expect(screen.getByRole('button', { name: 'Copy' })).toBeEnabled();
        expect(screen.getByRole('button', { name: 'Cut' })).toBeEnabled();
    });

    it('keeps only copy available for a read-only document with a selection', () => {
        const document = new JsonDataDocument('data.json', [1], true);
        document.setSelectedRows([0]);
        renderFooter(document);

        expect(screen.getByRole('button', { name: 'Copy' })).toBeEnabled();
        expect(screen.getByRole('button', { name: 'Add' })).toBeDisabled();
        expect(screen.getByRole('button', { name: 'Delete' })).toBeDisabled();
        expect(screen.getByRole('button', { name: 'Cut' })).toBeDisabled();
        expect(screen.getByRole('button', { name: 'Paste' })).toBeDisabled();
    });

    it('reports a clipboard failure through the dialog service and keeps the rows', async () => {
        const user = userEvent.setup();
        const clipboardError = new Error('clipboard denied');
        mocks.readTextFromClipboard.mockRejectedValueOnce(clipboardError);
        const document = new JsonDataDocument('data.json', [1], false);
        renderFooter(document);

        await user.click(screen.getByRole('button', { name: 'Paste' }));

        expect(mocks.dialogError).toHaveBeenCalledWith(clipboardError, { fallbackMessage: 'JSON rows could not be pasted' });
        expect(document.getValue()).toEqual([1]);
    });
});

